SELECT s.*,d.MONITOR_ENV,d.MONITOR_GROUP,d.DOCKER_SUMMARY,d.IS_ONLINE FROM MONITOR_DOCKER_STATS s LEFT JOIN MONITOR_DOCKER d ON s.SERVER_IP = d.SERVER_IP
AND s.SERVER_IP LIKE CONCAT('%', #{params.serverIp}, '%')
AND s.CONTAINER_NAME LIKE CONCAT('%', #{params.containerName}, '%')
AND d.MONITOR_ENV = #{params.monitorEnv}
AND d.MONITOR_GROUP = #{params.monitorGroup}

SELECT s.*,d.MONITOR_ENV,d.MONITOR_GROUP,d.DOCKER_SUMMARY,d.IS_ONLINE
FROM MONITOR_DOCKER_STATS s
LEFT JOIN MONITOR_DOCKER d ON s.SERVER_IP = d.SERVER_IP


        AND s.SERVER_IP = #{serverIp}


        AND s.CONTAINER_NAME = #{containerName}
